// Recupera el contexto previamente preparado para el análisis.
const contexto=$('11 - Preparar contexto para IA').first().json;

// Conserva únicamente políticas activas y completas.
const politicas=$input.all().map(item=>({recordId:item.json.id,...item.json.fields})).filter(p=>p['Estado de política']==='Activa'&&p.Política).sort((a,b)=>Number(a['Orden de prioridad']??999)-Number(b['Orden de prioridad']??999)).map(p=>({recordId:p.recordId,politica:p.Política,tipoCompensacion:p['Tipo de compensación'],valorCompensacion:p['Valor de compensación'],unidad:p.Unidad,categoriasAplicables:p['Categorías aplicables']??[],segmentosAplicables:p['Segmentos aplicables']??[],prioridadMinima:p['Prioridad mínima'],ordenPrioridad:Number(p['Orden de prioridad']??999),requiereAprobacionHumana:Boolean(p['Requiere aprobación humana']),requiereSupervisor:Boolean(p['Requiere supervisor']),restricciones:p.Restricciones??'',mensajeBase:p['Mensaje base']??''}));

// Devuelve un único item para realizar una sola llamada a OpenAI.
return[{json:{...contexto,politicas,cantidadPoliticas:politicas.length}}];

